private val dateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("d MMM yyyy")

fun LocalDate.display(): String = format(dateFormat)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  state: RegisterUiState,
  syncing: Boolean,
  banner: String?,
  onDismissBanner: () -> Unit,
  onRetry: () -> Unit,
  onPatientClick: (RegisterEntry) -> Unit,
) {
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("ANC register") },
        actions = { if (!syncing) TextButton(onClick = onRetry) { Text("Sync") } },
      )
    }
  ) { padding ->
    Column(Modifier.padding(padding).fillMaxSize()) {
      if (syncing) LinearProgressIndicator(Modifier.fillMaxWidth())
      banner?.let { Banner(it, onDismissBanner) }

      when (state) {
        is RegisterUiState.Loading -> Loading("Loading the register…")
        is RegisterUiState.Error -> ErrorMessage(state.message, onRetry)
        is RegisterUiState.Ready ->
          if (state.entries.isEmpty()) {
            EmptyMessage("No pregnant patients are currently on the register.")
          } else {
            LazyColumn(
              contentPadding = androidx.compose.foundation.layout.PaddingValues(16.dp),
              verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
              items(state.entries, key = { it.patientId }) { entry ->
                RegisterRow(entry) { onPatientClick(entry) }
              }
            }
          }
      }
    }
  }
}

@Composable
private fun RegisterRow(entry: RegisterEntry, onClick: () -> Unit) {
  Card(Modifier.fillMaxWidth().clickable(onClick = onClick)) {
    Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
      Text(entry.name, style = MaterialTheme.typography.titleMedium)
      Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {
        Text(
          entry.age?.let { "$it years" } ?: "Age unknown",
          style = MaterialTheme.typography.bodyMedium,
        )
        Text(
          entry.gestationalWeeks?.let { "$it weeks pregnant" } ?: "Gestation unknown",
          style = MaterialTheme.typography.bodyMedium,
        )
      }
      Text(
        "Due ${entry.dueDate.display()}",
        style = MaterialTheme.typography.bodyMedium,
        color = MaterialTheme.colorScheme.primary,
      )
    }
  }
}

@Composable
fun Banner(message: String, onDismiss: () -> Unit) {
  Row(
    Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp),
    verticalAlignment = Alignment.CenterVertically,
    horizontalArrangement = Arrangement.SpaceBetween,
  ) {
    Text(
      message,
      style = MaterialTheme.typography.bodySmall,
      color = MaterialTheme.colorScheme.error,
      modifier = Modifier.weight(1f),
    )
    TextButton(onClick = onDismiss) { Text("Dismiss") }
  }
}

@Composable
fun Loading(message: String) {
  Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
      CircularProgressIndicator()
      Text(message, Modifier.padding(top = 16.dp), style = MaterialTheme.typography.bodyMedium)
    }
  }
}

@Composable
fun ErrorMessage(message: String, onRetry: (() -> Unit)? = null) {
  Box(Modifier.fillMaxSize().padding(24.dp), contentAlignment = Alignment.Center) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
      Text(message, style = MaterialTheme.typography.bodyMedium)
      if (onRetry != null) TextButton(onClick = onRetry) { Text("Try again") }
    }
  }
}

@Composable
fun EmptyMessage(message: String) {
  Box(Modifier.fillMaxSize().padding(24.dp), contentAlignment = Alignment.Center) {
    Text(message, style = MaterialTheme.typography.bodyMedium)
  }
}
